import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-card-1-label';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasW = 2048, atlasH = 2048;
  const aspect = rect.w / rect.h;
  const planeH = 0.5;
  const planeW = planeH * aspect;

  const geometry = new THREE.PlaneGeometry(planeW, planeH);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  let disposeTexture = null;

  const tex = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png');
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;

  const offsetX = rect.x / atlasW;
  const offsetY = 1.0 - (rect.y + rect.h) / atlasH;
  const scaleX = rect.w / atlasW;
  const scaleY = rect.h / atlasH;

  const remappedUV = uv().mul(vec2(scaleX, scaleY)).add(vec2(offsetX, offsetY));
  material.colorNode = texture(tex, remappedUV);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'card-label-plane';
  group.add(mesh);

  const textMesh = ctx.fontAtlas.createText({
    text: 'Features 3',
    font: 'Lora',
    weight: 400,
    size: 39 / 512 * planeW,
    color: config.visual?.colors?.paper || '#e8ecf2',
    role: 'headline'
  });
  textMesh.position.set(0, 0, 0.001);
  group.add(textMesh);

  group.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
    if (textMesh && textMesh.userData?.cleanup) {
      textMesh.userData.cleanup();
    } else if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
    group.onBeforeRender = null;
  };

  return group;
}
